Here is the commit message:
net: ethernet: mtk_ppe: avoid NULL deref when gmac0 is
 disabled

If the gmac0 is disabled, the precheck for a valid ingress device will
cause a NULL pointer deref and crash the system. This happens because
eth->netdev[0] will be NULL but the code will directly try to access
netdev_ops.

Instead of just checking for the first net_device, it must be checked if
any of the mtk_eth net_devices is matching the netdev_ops of the ingress
device.

Cc: stable@vger.kernel.org
Fixes: 73cfd947dbdb ("net: ethernet: mtk_eth_soc: ppe: prevent ppe update for non-mtk devices")
Signed-off-by: Sven Eckelmann (Plasma Cloud) <se@simonwunderlich.de>
Reviewed-by: Simon Horman <horms@kernel.org>
Link: https://patch.msgid.link/20260324-wed-crash-gmac0-disabled-v1-1-3bc388aee565@simonwunderlich.de
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In the function `mtk_flow_offload_replace`, the code directly dereferences `eth->netdev[0]->netdev_ops` without first checking if `eth->netdev[0]` is non-NULL. When gmac0 (the first Ethernet interface) is disabled, `eth->netdev[0]` is NULL, leading to a NULL pointer dereference and system crash. The fix introduces a helper function that safely iterates over all netdev entries, skipping NULL pointers before comparing netdev_ops.

Here is the patch:

+static bool
+mtk_flow_is_valid_idev(const struct mtk_eth *eth, const struct net_device *idev)
+{
+	size_t i;
+
+	if (!idev)
+		return false;
+
+	for (i = 0; i < ARRAY_SIZE(eth->netdev); i++) {
+		if (!eth->netdev[i])
+			continue;
+
+		if (idev->netdev_ops == eth->netdev[i]->netdev_ops)
+			return true;
+	}
+
+	return false;
+}
+
 static int
 mtk_flow_offload_replace(struct mtk_eth *eth, struct flow_cls_offload *f,
 			 int ppe_index)
 {
 	struct flow_rule *rule = flow_cls_offload_flow_rule(f);
 	struct net_device *idev = NULL, *odev = NULL;
 	struct flow_action_entry *act;
 	struct mtk_flow_data data = {};
 	struct mtk_foe_entry foe;
 	struct mtk_flow_entry *entry;
 	int offload_type = 0;
 	int wed_index = -1;
 	u16 addr_type = 0;
 	u8 l4proto = 0;
 	int err = 0;
 	int i;

 	if (rhashtable_lookup(&eth->flow_table, &f->cookie, mtk_flow_ht_params))
 		return -EEXIST;

 	if (flow_rule_match_key(rule, FLOW_DISSECTOR_KEY_META)) {
 		struct flow_match_meta match;

 		flow_rule_match_meta(rule, &match);
 		if (mtk_is_netsys_v2_or_greater(eth)) {
 			idev = __dev_get_by_index(&init_net, match.key->ingress_ifindex);
-			if (idev && idev->netdev_ops == eth->netdev[0]->netdev_ops) {
+			if (mtk_flow_is_valid_idev(eth, idev)) {
 				struct mtk_mac *mac = netdev_priv(idev);

 				if (WARN_ON(mac->ppe_idx >= eth->soc->ppe_num))
 					return -EINVAL;

 				ppe_index = mac->ppe_idx;
 			}
 		}
 	} else {
 		return -EOPNOTSUPP;
 	}

 	if (flow_rule_match_key(rule, FLOW_DISSECTOR_KEY_CONTROL)) {
 		struct flow_match_control match;

 		flow_rule_match_control(rule, &match);
 		addr_type = match.key->addr_type;

 		if (flow_rule_has_control_flags(match.mask->flags,
 						f->common.extack))
 			return -EOPNOTSUPP;
 	} else {
 		return -EOPNOTSUPP;
 	}

 	if (flow_rule_match_key(rule, FLOW_DISSECTOR_KEY_BASIC)) {
 		struct flow_match_basic match;

 		flow_rule_match_basic(rule, &match);
 		l4proto = match.key->ip_proto;
 	} else {
 		return -EOPNOTSUPP;
 	}

 	switch (addr_type) {
 	case 0:
 		offload_type = MTK_PPE_PKT_TYPE_BRIDGE;
 		if (flow_rule_match_key(rule, FLOW_DISSECTOR_KEY_ETH_ADDRS)) {
 			struct flow_match_eth_addrs match;

 			flow_rule_match_eth_addrs(rule, &match);
 			memcpy(data.eth.h_dest, match.key->dst, ETH_ALEN);
 			memcpy(data.eth.h_source, match.key->src, ETH_ALEN);
 		} else {
 			return -EOPNOTSUPP;
 		}

 		if (flow_rule_match_key(rule, FLOW_DISSECTOR_KEY_VLAN)) {
 			struct flow_match_vlan match;

 			flow_rule_match_vlan(rule, &match);

 			if (match.key->vlan_tpid != cpu_to_be16(ETH_P_8021Q))
 				return -EOPNOTSUPP;

 			data.vlan_in = match.key->vlan_id;
 		}
 		break;
 	case FLOW_DISSECTOR_KEY_IPV4_ADDRS:
 		offload_type = MTK_PPE_PKT_TYPE_IPV4_HNAPT;
 		break;
 	case FLOW_DISSECTOR_KEY_IPV6_ADDRS:
 		offload_type = MTK_PPE_PKT_TYPE_IPV6_ROUTE_5T;
 		break;
 	default:
 		return -EOPNOTSUPP;
 	}

 	flow_action_for_each(i, act, &rule->action) {
 		switch (act->id) {
 		case FLOW_ACTION_MANGLE:
 			if (offload_type == MTK_PPE_PKT_TYPE_BRIDGE)
 				return -EOPNOTSUPP;
 			if (act->mangle.htype == FLOW_ACT_MANGLE_HDR_TYPE_ETH)
 				mtk_flow_offload_mangle_eth(act, &data.eth);
 			break;
 		case FLOW_ACTION_REDIRECT:
 			odev = act->dev;
 			break;
 		case FLOW_ACTION_CSUM:
 			break;
 		case FLOW_ACTION_VLAN_PUSH:
 			if (data.vlan.num + data.pppoe.num == 2 ||
 			    act->vlan.proto != htons(ETH_P_8021Q))
 				return -EOPNOTSUPP;

 			data.vlan.vlans[data.vlan.num].id = act->vlan.vid;
 			data.vlan.vlans[data.vlan.num].proto = act->vlan.proto;
 			data.vlan.num++;
 			break;
 		case FLOW_ACTION_VLAN_POP:
 			break;
 		case FLOW_ACTION_PPPOE_PUSH:
 			if (data.pppoe.num == 1 ||
 			    data.vlan.num == 2)
 				return -EOPNOTSUPP;

 			data.pppoe.sid = act->pppoe.sid;
 			data.pppoe.num++;
 			break;
 		default:
 			return -EOPNOTSUPP;
 		}
 	}

 	if (!is_valid_ether_addr(data.eth.h_source) ||
 	    !is_valid_ether_addr(data.eth.h_dest))
 		return -EINVAL;

 	err = mtk_foe_entry_prepare(eth, &foe, offload_type, l4proto, 0,
 				    data.eth.h_source, data.eth.h_dest);
 	if (err)
 		return err;

 	if (flow_rule_match_key(rule, FLOW_DISSECTOR_KEY_PORTS)) {
 		struct flow_match_ports ports;

 		if (offload_type == MTK_PPE_PKT_TYPE_BRIDGE)
 			return -EOPNOTSUPP;

 		flow_rule_match_ports(rule, &ports);
 		data.src_port = ports.key->src;
 		data.dst_port = ports.key->dst;
 	} else if (offload_type != MTK_PPE_PKT_TYPE_BRIDGE) {
 		return -EOPNOTSUPP;
 	}

 	if (addr_type == FLOW_DISSECTOR_KEY_IPV4_ADDRS) {
 		struct flow_match_ipv4_addrs addrs;

 		flow_rule_match_ipv4_addrs(rule, &addrs);

 		data.v4.src_addr = addrs.key->src;
 		data.v4.dst_addr = addrs.key->dst;

 		mtk_flow_set_ipv4_addr(eth, &foe, &data, false);
 	}

 	if (addr_type == FLOW_DISSECTOR_KEY_IPV6_ADDRS) {
 		struct flow_match_ipv6_addrs addrs;

 		flow_rule_match_ipv6_addrs(rule, &addrs);

 		data.v6.src_addr = addrs.key->src;
 		data.v6.dst_addr = addrs.key->dst;

 		mtk_flow_set_ipv6_addr(eth, &foe, &data);
 	}

 	flow_action_for_each(i, act, &rule->action) {
 		if (act->id != FLOW_ACTION_MANGLE)
 			continue;

 		if (offload_type == MTK_PPE_PKT_TYPE_BRIDGE)
 			return -EOPNOTSUPP;

 		switch (act->mangle.htype) {
 		case FLOW_ACT_MANGLE_HDR_TYPE_TCP:
 		case FLOW_ACT_MANGLE_HDR_TYPE_UDP:
 			err = mtk_flow_mangle_ports(act, &data);
 			break;
 		case FLOW_ACT_MANGLE_HDR_TYPE_IP4:
 			err = mtk_flow_mangle_ipv4(act, &data);
 			break;
 		case FLOW_ACT_MANGLE_HDR_TYPE_ETH:
 			/* handled earlier */
 			break;
 		default:
 			return -EOPNOTSUPP;
 		}

 		if (err)
 			return err;
 	}

 	if (addr_type == FLOW_DISSECTOR_KEY_IPV4_ADDRS) {
 		err = mtk_flow_set_ipv4_addr(eth, &foe, &data, true);
 		if (err)
 			return err;
 	}

 	if (offload_type == MTK_PPE_PKT_TYPE_BRIDGE)
 		foe.bridge.vlan = data.vlan_in;

 	for (i = 0; i < data.vlan.num; i++)
 		mtk_foe_entry_set_vlan(eth, &foe, data.vlan.vlans[i].id);

 	if (data.pppoe.num == 1)
 		mtk_foe_entry_set_pppoe(eth, &foe, data.pppoe.sid);

 	err = mtk_flow_set_output_device(eth, &foe, odev, data.eth.h_dest,
 					 &wed_index);
 	if (err)
 		return err;

 	if (wed_index >= 0 && (err = mtk_wed_flow_add(wed_index)) < 0)
 		return err;

 	entry = kzalloc_obj(*entry);
 	if (!entry)
 		return -ENOMEM;

 	entry->cookie = f->cookie;
 	memcpy(&entry->data, &foe, sizeof(entry->data));
 	entry->wed_index = wed_index;
 	entry->ppe_index = ppe_index;

 	err = mtk_foe_entry_commit(eth->ppe[entry->ppe_index], entry);
 	if (err < 0)
 		goto free;

 	err = rhashtable_insert_fast(&eth->flow_table, &entry->node,
 				     mtk_flow_ht_params);
 	if (err < 0)
 		goto clear;

 	return 0;

 clear:
 	mtk_foe_entry_clear(eth->ppe[entry->ppe_index], entry);
 free:
 	kfree(entry);
 	if (wed_index >= 0)
 	    mtk_wed_flow_remove(wed_index);
 	return err;
 }



